import {
  FAMILY_GROUPS,
  FAMILY_NAMES,
  candidateFromGraph,
  createGraph,
  familyCategory,
  randomSeed,
} from "./generator.js";

// The grammar and its macro-category ledger are defined together in
// generator.js. Re-exported here because the schedule is the reason the
// grouping exists.
export { FAMILY_GROUPS, familyCategory };
import { descriptorDistance } from "./perception.js";

const clamp01 = (value) => Math.max(0, Math.min(1, value));

function mix(a, b, amount) {
  return a + (b - a) * amount;
}

function shuffle(values, rng = Math.random) {
  const result = [...values];
  for (let index = result.length - 1; index > 0; index -= 1) {
    const swap = Math.floor(rng() * (index + 1));
    [result[index], result[swap]] = [result[swap], result[index]];
  }
  return result;
}

/**
 * Bias the authored grammar towards visually articulated, layered outputs.
 * The transformation is deterministic for a given seed because it only uses
 * values already generated by createGraph(). It does not optimise against a
 * visitor model and does not infer preference.
 */
export function enrichGraph(graph) {
  const next = structuredClone(graph);
  const t = next.traits;

  // Lift the floor away from degenerate values without collapsing the range.
  // An earlier revision pushed every trait towards the top of its span, which
  // made every result busy and dense: articulation, but no contrast between
  // one encounter and the next. Sparse, quiet and slow results are legitimate
  // outcomes and are now reachable.
  t.complexity = mix(0.42, 1, t.complexity);
  t.density = mix(0.12, 1, t.density);
  t.turbulence = mix(0.08, 1, t.turbulence);
  t.depth = mix(0.14, 1, t.depth);
  t.contrast = mix(0.1, 0.96, t.contrast);

  // Preserve quiet and sparse regions within complex programs. Complexity is
  // not treated as uniform maximal density.
  if (t.softness > 0.72) t.density *= 0.72;
  if (t.symmetry > 0.82) t.rotation = 1 - t.rotation;
  if (t.tempo > 0.86) t.tempo = 0.55 + (t.tempo - 0.86) * 0.45;

  next.generator = "tsdne-procedural-v2";
  return next;
}

export function generateComplexCandidate(seed = randomSeed(), family = null) {
  const graph = enrichGraph(createGraph(seed, family));
  return candidateFromGraph(graph, {
    seed,
    origin: "authored-procedural",
  });
}

export function visualComplexityScore(candidate) {
  const p = candidate.perception;
  if (!p) return 0;

  const variance = clamp01(Math.sqrt(Math.max(0, p.variance)) / 112);
  const edge = clamp01(p.edge / 58);
  const motion = clamp01(p.temporal / 36);
  const dynamicRange = clamp01(1 - Math.abs(p.mean - 126) / 126);
  const saturationBalance = clamp01(1 - Math.abs(p.saturation - 0.28) / 0.72);
  const programDepth = clamp01((candidate.estimatedCost - 5) / 12);

  // Edge energy is deliberately under-weighted relative to variance. A dithered
  // or grained surface maximises per-pixel edge without adding any structure,
  // and scoring it highly quietly turns one reprographic finish into the house
  // style the rest of this work is trying to avoid.
  return (
    variance * 0.28 +
    edge * 0.17 +
    motion * 0.14 +
    dynamicRange * 0.17 +
    saturationBalance * 0.1 +
    programDepth * 0.14
  );
}

export function nearestPerceptualDistance(candidate, traces) {
  if (!traces.length) return 1;
  let nearest = 1;
  for (const trace of traces) {
    nearest = Math.min(nearest, descriptorDistance(candidate.perception, trace.perception));
  }
  return nearest;
}

export function familyDistance(candidate, recentFamilies) {
  if (!recentFamilies.length) return 1;
  const latest = recentFamilies.at(-1);
  if (candidate.family === latest) return 0;
  const occurrences = recentFamilies.filter((family) => family === candidate.family).length;
  return clamp01(1 - occurrences / Math.max(2, recentFamilies.length));
}

/**
 * Separation on the colour axis. Structure and colour vary independently, so a
 * run of unrelated structures rendered in the same ink still reads as a run of
 * the same thing. Recent modes are held in memory for the session only and are
 * never written to the local trace store.
 */
export function modeDistance(candidate, recentModes) {
  if (!recentModes.length || !candidate.colorMode) return 1;
  if (candidate.colorMode === recentModes.at(-1)) return 0;
  const occurrences = recentModes.filter((mode) => mode === candidate.colorMode).length;
  return clamp01(1 - occurrences / Math.max(2, recentModes.length));
}

/**
 * Selects a candidate by maximin perceptual distance, quality and temporary
 * family separation. This is sequence-level quality control, not a model of
 * the visitor. All traces are local, bounded and non-reconstructive.
 */
export function scoreCandidate(
  candidate,
  traces,
  recentFamilies,
  { earlyEncounter = false, recentModes = [] } = {},
) {
  const novelty = nearestPerceptualDistance(candidate, traces);
  const complexity = visualComplexityScore(candidate);
  const family = familyDistance(candidate, recentFamilies);
  const mode = modeDistance(candidate, recentModes);

  const weights = earlyEncounter
    ? { novelty: 0.54, complexity: 0.16, family: 0.2, mode: 0.1 }
    : { novelty: 0.44, complexity: 0.24, family: 0.22, mode: 0.1 };

  return {
    score:
      novelty * weights.novelty +
      complexity * weights.complexity +
      family * weights.family +
      mode * weights.mode,
    novelty,
    complexity,
    family,
    mode,
  };
}

export function selectCandidate(
  candidates,
  traces,
  recentFamilies,
  { earlyEncounter = false, recentModes = [] } = {},
) {
  if (!candidates.length) throw new Error("No valid candidates were available.");

  const ranked = candidates
    .map((candidate) => ({
      candidate,
      ...scoreCandidate(candidate, traces, recentFamilies, { earlyEncounter, recentModes }),
    }))
    .sort((a, b) => b.score - a.score);

  return ranked[0];
}

function stratifiedRound(groups, rng) {
  const queues = groups.map((families) => shuffle(families, rng));
  const result = [];
  let order = shuffle(queues.map((_, index) => index), rng);

  while (queues.some((queue) => queue.length)) {
    for (const index of order) {
      if (queues[index].length) result.push(queues[index].shift());
    }
    order = shuffle(order, rng);
  }
  return result;
}

/**
 * Attempt order for a public candidate pool. Eligible families are shuffled
 * within their macro-categories and then interleaved across categories. This
 * avoids the earlier artefact in which an early-stopping pool often sampled a
 * contiguous neighbourhood of the categorically ordered FAMILY_NAMES list.
 *
 * This is still an artistic selector, not the sampling design of the private
 * generator study. The research instrument uses explicit balanced sampling so
 * that family quality can be estimated without inheriting public-selector bias.
 */
export function familySchedule(
  recentFamilies,
  count = FAMILY_NAMES.length,
  rng = Math.random,
) {
  const recent = new Set(recentFamilies.slice(-6));
  let groups = Object.values(FAMILY_GROUPS)
    .map((families) => families.filter((family) => !recent.has(family)))
    .filter((families) => families.length);

  const eligibleCount = groups.reduce((sum, group) => sum + group.length, 0);
  if (eligibleCount < 8) groups = Object.values(FAMILY_GROUPS).map((group) => [...group]);

  const schedule = [];
  while (schedule.length < count) {
    const round = stratifiedRound(groups, rng);
    schedule.push(...round.slice(0, count - schedule.length));
  }
  return schedule;
}
